<?php require "db.php"; $pageTitle="Dashboard"; function total($c,$t){$ok=["vehicles","drivers","trips","maintenance"];if(!in_array($t,$ok))return 0;$r=$c->query("SELECT COUNT(*) n FROM $t");return (int)$r->fetch_assoc()["n"];} $v=total($conn,"vehicles");$d=total($conn,"drivers");$t=total($conn,"trips");$m=total($conn,"maintenance");$recent=$conn->query("SELECT t.*,v.vehicle_number,d.name driver_name FROM trips t LEFT JOIN vehicles v ON v.id=t.vehicle_id LEFT JOIN drivers d ON d.id=t.driver_id ORDER BY t.id DESC LIMIT 5");include "includes/header.php"; ?>
<section class="hero"><div><p class="eyebrow">FLEET OPERATIONS OVERVIEW</p><h1>Manage every mile<br>with confidence.</h1><p>Track vehicles, coordinate drivers, monitor trips and plan maintenance from one simple dashboard.</p><a class="button" href="trips.php">Manage trips →</a></div><div class="hero-art">🚚<span>📍</span></div></section>
<div class="stats"><div class="stat"><span>🚛 Vehicles</span><strong><?=$v?></strong><small>Registered fleet</small></div><div class="stat"><span>👨‍✈️ Drivers</span><strong><?=$d?></strong><small>Available team</small></div><div class="stat"><span>🧭 Trips</span><strong><?=$t?></strong><small>Trips recorded</small></div><div class="stat"><span>🛠️ Maintenance</span><strong><?=$m?></strong><small>Service records</small></div></div>
<section class="panel"><div class="section-head"><div><p class="eyebrow">LATEST ACTIVITY</p><h2>Recent trips</h2></div><a class="text-link" href="trips.php">View all →</a></div><?php if($recent&&$recent->num_rows):?><div class="table-wrap"><table><tr><th>Trip</th><th>Route</th><th>Date</th><th>Vehicle</th><th>Driver</th><th>Status</th></tr><?php while($r=$recent->fetch_assoc()):?><tr><td>#<?=$r["id"]?></td><td><?=htmlspecialchars($r["origin"])?> → <?=htmlspecialchars($r["destination"])?></td><td><?=htmlspecialchars($r["trip_date"])?></td><td><?=htmlspecialchars($r["vehicle_number"]??"—")?></td><td><?=htmlspecialchars($r["driver_name"]??"—")?></td><td><span class="badge"><?=htmlspecialchars($r["status"])?></span></td></tr><?php endwhile;?></table></div><?php else:?><div class="empty"><h3>No trips yet</h3><p>Add your first trip to see fleet activity.</p><a class="button" href="trips.php">Add a trip</a></div><?php endif;?></section><?php include "includes/footer.php";?>